#!/usr/bin/env python3
"""Generate frontend/src/lib/prefill.ts from contracts/prefill.py (sprint step 0). Run: uv run python scripts/gen-prefill.py"""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from contracts.prefill import HOME_TYPES, PREFILL, YES_NO  # noqa: E402

OUT = ROOT / "frontend" / "src" / "lib" / "prefill.ts"


def render() -> str:
    return (
        "// Generated by scripts/gen-prefill.py from contracts/prefill.py. Do not edit by hand.\n"
        "// Prefill query parameters for every form (docs/SPRINT.md). Pages fill fields from these and never submit.\n\n"
        f"export const YES_NO = {json.dumps(list(YES_NO))} as const;\n"
        f"export const HOME_TYPES = {json.dumps(list(HOME_TYPES))} as const;\n\n"
        f"export const PREFILL = {json.dumps(PREFILL, indent=2)} as const;\n\n"
        "export type PrefillForm = keyof typeof PREFILL;\n"
        "export type PrefillParam<F extends PrefillForm> = keyof (typeof PREFILL)[F][\"params\"];\n"
    )


if __name__ == "__main__":
    OUT.write_text(render())
    print(f"wrote {OUT.relative_to(ROOT)}")
